INSERT INTO feature VALUES('native-emitter','runtime','A native emitter by copy-and-patch',NULL,'implemented','uncommon','dependent provers','One definition of the L machine''s transitions generates the copy-and-patch stencils and the portable executor; every runs item of the corpus executes as patched native code by default under a content-hash cache (GANDR_NATIVE=always|never|cached), native and executor agreeing item for item; macOS arm64 and Linux x86-64 patchers; the hand-written machine retired, the executor the reference; each thread holds its own regions, so two runs on two threads answer as they do on one.','runtime-stencils runtime-emitter','crates/runtime-stencils/tests/agreement.rs crates/runtime-emitter/tests/agreement.rs crates/core-sequent/tests/differential.rs corpus/model crates/surface-evaluate/src/evaluate.rs',NULL,'#536');
